            );
            pathland_qt_layer_reset();
            f();
            pathland_qt_layer_shutdown();
        }
    }

    /// The captured `FIT_CHANGED` events as `(node id, index)`.
    fn captured_fit_changes() -> Vec<(u32, i32)> {
        EVENTS
